#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<int,int> pii;
typedef vector<int> vi;

#define rep(i,a,b) for(int i=(a);i<(b);i++)
#define fi first
#define se second
#define de(x) cout<<#x<<"="<<x<<"\n"
#define dd(x) cout<<#x<<"="<<x<<" "
#define pb(x) push_back(x)
#define all(x) x.begin(),x.end()
#define sz(x) (int)x.size()
#define lowbit(a) ((a)&-(a))
#define per(i,a,b) for(int i=(b)-1;i>=(a);--i)
const int N=2e5+5;
const int inf= ~0U>>1;
template<class U,class V>
struct MCMF{
    static const int N = 30000, M = 7010010;
    int h[N], ing[N], pre[N], to[M], ne[M], e, s, t, n;
    U cap[M]; V dis[N], cost[M];
    void initialize(int _n = N){ fill(h , h + (n=_n) , -1); e = 0;}
    void addEdge(int u,int v,U c,V w){ to[e] = v; ne[e] = h[u]; cap[e] = c; cost[e] = w; h[u] = e++;}
    void connect(int u,int v,U c,V w){ addEdge(u,v,c,w); addEdge(v,u,0,-w); }
    bool spfa(){
        queue<int> Q;
        fill(dis, dis+n, inf);
        Q.push(s), ing[s] = 1, dis[s] = 0;
        while(!Q.empty()){
            int c = Q.front(); Q.pop(); ing[c] = 0;
            for(int k = h[c]; ~k; k = ne[k]) if (cap[k] > 0) {
                int v = to[k];
                if(dis[c] + cost[k] < dis[v]){
                    dis[v] = dis[c] + cost[k];
                    pre[v] = k;
                    if(!ing[v]) Q.push(v) , ing[v] = 1;
                }
            }
        }
        return dis[t] != inf;
    }
    U flow; V mincost;
    pair<U, V> execute(int _s,int _t){
        s = _s , t = _t;
        flow = mincost = 0;
        while(spfa()){
            U minFlow = inf; int p, k;
            for(p = t;p != s;p = to[k^1]) minFlow = min(minFlow, cap[k = pre[p]]);
            for(p = t;p != s;p = to[k^1]) cap[k = pre[p]] -= minFlow, cap[k^1] += minFlow;
            mincost += minFlow * dis[t];
            flow += minFlow;
        }
        return make_pair(flow, mincost);
    }
};
MCMF<int,int> flow;
int n , m , k ,c , d ,a[N] , id[55][2500];
int main(){
	scanf("%d%d%d%d%d",&n,&m,&k,&c,&d);
	rep(i , 1 , k + 1)
		scanf("%d",&a[i]);
	flow.initialize(50*50*4 + 10);
	int s = flow.n - 2,t = flow.n - 3;
	int cnt = 0 ,mx = 100;
	rep(i , 1 , n + 1)
		rep(j , 0 , mx + 1)
			id[i][j] = ++cnt;
	int u , v;
	rep(i , 1 , m + 1){
		scanf("%d%d",&u,&v);
		rep(j , 0 , mx){
			rep(h , 1 , k + 1){
				int tmp = h*h*d - (h-1)*(h-1)*d;
				flow.connect(id[u][j] , id[v][j + 1] , 1 , c + tmp);
				flow.connect(id[v][j] , id[u][j + 1] , 1 , c + tmp);
			}
		}
	}
	rep(i , 1 , n + 1)
		rep(j , 0 , mx)
			flow.connect(id[i][j] , id[i][j + 1] , inf , c);
	rep(i , 1 , k + 1)
		flow.connect(s , id[a[i]][0] , 1 , 0);
	rep(j , 1 , mx + 1)flow.connect(id[1][j] , t , inf , 0);
	int ans = flow.execute(s , t).se;
	printf("%d\n",ans);
	return 0;
}
